import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../core/api/api_client.dart';
import '../../core/auth/auth_controller.dart';
import 'onboarding_models.dart';

class OnboardingScreen extends ConsumerStatefulWidget { const OnboardingScreen({super.key}); @override ConsumerState<OnboardingScreen> createState() => _OnboardingState(); }
class _OnboardingState extends ConsumerState<OnboardingScreen> {
  OnboardingDraft draft = OnboardingDraft(); final amount = TextEditingController(); String? error; bool busy = false;
  static const titles = ['Базовая валюта', 'Доступные деньги', 'Будущие доходы', 'Обязательные расходы', 'Долги', 'Защищённый резерв', 'Проверка'];
  @override void initState() { super.initState(); _restore(); }
  @override void dispose() { amount.dispose(); super.dispose(); }
  Future<void> _restore() async { final raw = await ref.read(storageProvider).read('onboarding_draft'); if (raw == null) return; try { final data = jsonDecode(raw); if (data is Map<String,dynamic> && mounted) setState(() { draft = OnboardingDraft.fromJson(data); _syncAmount(); }); } catch (_) { await ref.read(storageProvider).delete('onboarding_draft'); } }
  void _syncAmount() { amount.text = ((draft.step == 1 ? draft.available : draft.reserve) / 100).toStringAsFixed(2); }
  Future<void> _save() => ref.read(storageProvider).write('onboarding_draft', jsonEncode(draft.toJson()));
  Future<void> _changed(VoidCallback change) async { setState(change); await _save(); }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: Text('${draft.step + 1} из 7'), leading: IconButton(icon: Icon(draft.step == 0 ? Icons.close : Icons.arrow_back), onPressed: busy ? null : () async { if (draft.step == 0) return context.go('/welcome'); await _changed(() => draft.step--); _syncAmount(); })), body: SafeArea(child: ListView(padding: const EdgeInsets.all(24), children: [LinearProgressIndicator(value: (draft.step + 1) / 7), const SizedBox(height: 24), Text(titles[draft.step], style: Theme.of(context).textTheme.headlineMedium), const SizedBox(height: 20), _content(), if (error != null) Padding(padding: const EdgeInsets.only(top: 12), child: Text(error!, style: TextStyle(color: Theme.of(context).colorScheme.error))), const SizedBox(height: 20), FilledButton(onPressed: busy ? null : _next, child: Text(draft.step == 6 ? 'Получить план' : 'Продолжить'))]));
  Widget _content() { switch (draft.step) { case 0: return Column(children: ['RUB','USD','EUR'].map((c) => RadioListTile<String>(value: c, groupValue: draft.currency, title: Text(c), onChanged: (v) { if (v != null) _changed(() => draft.currency = v); })).toList()); case 1: case 5: return TextField(controller: amount, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: InputDecoration(labelText: draft.step == 1 ? 'Сумма сейчас' : 'Минимальный резерв', helperText: 'Например: 12500,50'), onChanged: (_) => _saveAmount(silent: true)); case 2: return _items('Доходов пока нет', draft.incomes, (x) => '${x.name} · ${(x.amount/100).toStringAsFixed(2)} · ${day(x.date)}', _income); case 3: return _items('Расходов пока нет', draft.expenses, (x) => '${x.name} · ${(x.amount/100).toStringAsFixed(2)} · ${day(x.date)}', _expense); case 4: return _items('Долгов пока нет', draft.debts, (x) => '${x.name} · ${(x.balance/100).toStringAsFixed(2)} · ${(x.rateBps/100).toStringAsFixed(2)}%', _debt); default: return Text('Валюта: ${draft.currency}\nДоступно: ${(draft.available/100).toStringAsFixed(2)}\nДоходы: ${draft.incomes.length}\nРасходы: ${draft.expenses.length}\nДолги: ${draft.debts.length}\nРезерв: ${(draft.reserve/100).toStringAsFixed(2)}'); } }
  Widget _items<T>(String empty, List<T> items, String Function(T) label, Future<T?> Function([T?]) editor) => Column(children: [if(items.isEmpty) Padding(padding: const EdgeInsets.all(20), child: Text(empty)), ...items.asMap().entries.map((entry) => ListTile(title: Text(label(entry.value)), onTap: () async { final changed = await editor(entry.value); if(changed != null) await _changed(() => items[entry.key] = changed); }, trailing: IconButton(icon: const Icon(Icons.delete_outline), onPressed: () => _changed(() => items.removeAt(entry.key))))), OutlinedButton.icon(onPressed: () async { final created = await editor(); if(created != null) await _changed(() => items.add(created)); }, icon: const Icon(Icons.add), label: const Text('Добавить'))]);
  Future<IncomeDraft?> _income([IncomeDraft? old]) => _editEntry(kind: 'Доход', oldName: old?.name, oldAmount: old?.amount, oldDate: old?.date, confirmed: old?.confirmed ?? true, recurring: old?.recurring ?? false, build: (n,a,d,c,r,_,__,___) => IncomeDraft(name:n,amount:a,date:d,confirmed:c,recurring:r));
  Future<ExpenseDraft?> _expense([ExpenseDraft? old]) => _editEntry(kind: 'Расход', oldName: old?.name, oldAmount: old?.amount, oldDate: old?.date, recurring: old?.recurring ?? false, build: (n,a,d,_,r,__,___,____) => ExpenseDraft(name:n,amount:a,date:d,recurring:r));
  Future<DebtDraft?> _debt([DebtDraft? old]) => _editEntry(kind: 'Долг', oldName: old?.name, oldAmount: old?.balance, oldDate: old?.nextPayment, rateBps: old?.rateBps, minimum: old?.minimum, overdue: old?.overdue ?? false, build: (n,a,d,_,__,rate,min,overdue) => DebtDraft(name:n,balance:a,rateBps:rate,minimum:min,nextPayment:d,overdue:overdue));
  Future<T?> _editEntry<T>({required String kind, String? oldName, int? oldAmount, DateTime? oldDate, bool confirmed=true, bool recurring=false, int? rateBps, int? minimum, bool overdue=false, required T Function(String,int,DateTime,bool,bool,int,int,bool) build}) async { final name=TextEditingController(text:oldName); final money=TextEditingController(text:oldAmount==null?'':(oldAmount/100).toStringAsFixed(2)); final date=TextEditingController(text:day(oldDate ?? DateTime.now().add(const Duration(days:7)))); final rate=TextEditingController(text:rateBps==null?'':(rateBps/100).toStringAsFixed(2)); final min=TextEditingController(text:minimum==null?'':(minimum/100).toStringAsFixed(2)); String? validation; final result=await showDialog<T>(context:context,builder:(dialogContext)=>StatefulBuilder(builder:(context,setLocal)=>AlertDialog(scrollable:true,title:Text(kind),content:Column(children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Название')),const SizedBox(height:12),TextField(controller:money,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Сумма')),const SizedBox(height:12),TextField(controller:date,decoration:const InputDecoration(labelText:'Дата YYYY-MM-DD')),if(kind=='Долг') ...[const SizedBox(height:12),TextField(controller:rate,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Годовая ставка, %')),const SizedBox(height:12),TextField(controller:min,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Минимальный платёж'))],if(kind=='Доход') CheckboxListTile(value:confirmed,title:const Text('Подтверждён'),onChanged:(v)=>setLocal(()=>confirmed=v??false)),if(kind!='Долг') CheckboxListTile(value:recurring,title:const Text('Регулярный'),onChanged:(v)=>setLocal(()=>recurring=v??false)),if(kind=='Долг') CheckboxListTile(value:overdue,title:const Text('Есть просрочка'),onChanged:(v)=>setLocal(()=>overdue=v??false)),if(validation!=null)Text(validation!,style:TextStyle(color:Theme.of(context).colorScheme.error))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Отмена')),FilledButton(onPressed:(){final n=name.text.trim(), a=parseMoney(money.text), d=parseDate(date.text); final rateValue=kind=='Долг'?double.tryParse(rate.text.replaceAll(',','.')):0; final rateMinor=rateValue==null?-1:(rateValue*100).round(); final minimumValue=kind=='Долг'?parseMoney(min.text):0; if(n.isEmpty||a==null||d==null){setLocal(()=>validation='Заполните название, положительную сумму и корректную дату');return;} if(kind=='Доход'&&d.isBefore(DateTime(DateTime.now().year,DateTime.now().month,DateTime.now().day))){setLocal(()=>validation='Ожидаемый доход не может быть в прошлом');return;} if(kind=='Долг'&&(rateMinor<0||rateMinor>100000||minimumValue==null||minimumValue>a)){setLocal(()=>validation='Проверьте ставку (0–1000%) и платёж не больше остатка');return;} Navigator.pop(context,build(n,a,d,confirmed,recurring,rateMinor,minimumValue??0,overdue));},child:const Text('Сохранить'))]))); name.dispose();money.dispose();date.dispose();rate.dispose();min.dispose();return result; }
  Future<bool> _saveAmount({bool silent=false}) async { final parsed=parseMoney(amount.text,allowZero:true); if(parsed==null){if(!silent)setState(()=>error='Введите сумму от 0 до 1 000 000 000 с максимум 2 знаками');return false;} if(draft.step==1)draft.available=parsed; else draft.reserve=parsed; await _save(); return true; }
  Future<void> _next() async { setState(()=>error=null); if((draft.step==1||draft.step==5)&&!await _saveAmount())return; if(draft.step<6){await _changed(()=>draft.step++);_syncAmount();return;} setState(()=>busy=true); try { await ref.read(apiClientProvider).completeOnboarding(draft.payload(),draft.idempotencyKey); ref.read(authControllerProvider.notifier).completed(); if(mounted)context.go('/today'); } catch(e){if(mounted)setState(()=>error=e.toString());} finally{if(mounted)setState(()=>busy=false);} }
}
